import unittest

from pricing import discounted_price


class DiscountedPriceTests(unittest.TestCase):
    def test_applies_normal_discount(self):
        self.assertEqual(discounted_price(1000, 25), 750)

    def test_handles_full_discount(self):
        self.assertEqual(discounted_price(999, 100), 0)

    def test_uses_rounding(self):
        self.assertEqual(discounted_price(999, 33), round(999 * 0.67))

    def test_rejects_invalid_values(self):
        with self.assertRaises(ValueError):
            discounted_price(-1, 10)
        with self.assertRaises(ValueError):
            discounted_price(100, -5)


if __name__ == "__main__":
    unittest.main()
